const project = config.mergeConfig(config.createDefaultConfig(), request.project ?? {});
const result = await native.loadEvalWithParams(request.evalPath, { suiteParams: project.params });
let fixtures = request.fixtures;
if (fixtures) {
  const sidecar = request.params === undefined ? undefined : native.parseAndValidateParams(request.params);
  const merged = native.mergeParams(project.params, sidecar?.params);
  const scalars = Object.fromEntries(Object.entries(merged).filter(([, value]) => native.isScalarParamValue(value)));
  const expansion = result.paramsUsed
    ? native.computeExpansion(result.resolvedParams, sidecar?.name_suffix)
    : { combinations: [{}] };
  const perCombination = result.spec.stimuli.length / expansion.combinations.length;
  const resolved = [];
  for (const fixture of fixtures) {
    let matches = 0;
    for (const [index, params] of expansion.combinations.entries()) {
      const item = JSON.parse(native.interpolateParams(JSON.stringify(fixture), { ...scalars, ...params }));
      const names = result.spec.stimuli.slice(index * perCombination, (index + 1) * perCombination).map(item => item.name);
      if (names.includes(item.stimulus)) { resolved.push(item); matches++; }
    }
    if (!matches) throw new Error("Fixture must select an exact expanded stimulus name; do not select an ambiguous base name.");
  }
  fixtures = resolved;
}
process.stdout.write(JSON.stringify({ spec: result.spec, fixtures, combinationCount: result.combinationCount }));
